int delta_offset = 0;
for (int i = 0; i < path->segment_count - 1;
     ++i, delta_offset += (int)sizeof(PathTemplateSample)) {
    PathTemplateSample* primary =
        (PathTemplateSample*)((char*)path->primary_samples + delta_offset);
    PathTemplateSample* primary_next = primary + 1;
    primary->delta_dir_to_next =
        primary_next->transform.position - primary->transform.position;
    primary->delta_length = primary->delta_dir_to_next.Normalize();

    PathTemplateSample* secondary =
        (PathTemplateSample*)((char*)path->secondary_samples + delta_offset);
    PathTemplateSample* secondary_next = secondary + 1;
    secondary->delta_dir_to_next =
        secondary_next->transform.position - secondary->transform.position;
    secondary->delta_length = secondary->delta_dir_to_next.Normalize();
}
